import type { OperationalTransaction } from '../components/OperationalTransactionsTable';

export interface OperationalExportRow {
  date: string;
  source: string;
  category: string;
  amount: number;
  classification: string;
  products: string;
  co2Kg: number;
  description?: string;
}

export const buildOperationalExportRows = (
  transactions: OperationalTransaction[],
  options: {
    includeDescription: boolean;
    formatSourceLabel: (txn: OperationalTransaction) => string;
    resolveBoundary: (txn: OperationalTransaction) => 'company' | 'product';
  }
): OperationalExportRow[] =>
  transactions.map((txn) => {
    const products = (txn.productAttribution?.assignedProducts || [])
      .map((item) => item.productName)
      .filter(Boolean)
      .join('; ');
    const boundary = options.resolveBoundary(txn);

    return {
      date: new Date(txn.date).toISOString().slice(0, 10),
      source: options.formatSourceLabel(txn),
      category: txn.category || 'other',
      amount: Number(txn.amount || 0),
      classification: boundary === 'product' ? 'Manufactured product' : 'Company',
      products,
      co2Kg: Number(txn.carbonFootprint?.co2Emissions || 0),
      ...(options.includeDescription ? { description: txn.description || '' } : {}),
    };
  });

export const operationalRowsToCsv = (rows: OperationalExportRow[]): string => {
  if (rows.length === 0) {
    return '';
  }

  const headers = Object.keys(rows[0]);
  const escape = (value: unknown) => {
    const text = String(value ?? '');
    if (/[",\n]/.test(text)) {
      return `"${text.replace(/"/g, '""')}"`;
    }
    return text;
  };

  const lines = [
    headers.join(','),
    ...rows.map((row) => headers.map((key) => escape(row[key as keyof OperationalExportRow])).join(',')),
  ];
  return lines.join('\n');
};

export const downloadOperationalCsv = (csv: string, filename = 'operational-transactions.csv') => {
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = filename;
  link.click();
  URL.revokeObjectURL(url);
};
